<script setup lang="ts">import { onMounted,ref } from 'vue';import { ElMessage,ElMessageBox,type FormInstance } from 'element-plus';import { Edit3,Plus,Trash2 } from 'lucide-vue-next';import ResourceState from '@/components/common/ResourceState.vue';import { createEnterprise,deleteEnterprise,getEnterpriseList,updateEnterprise,type EnterpriseRecord } from '@/api/project';const data=ref<EnterpriseRecord[]>([]),loading=ref(false),error=ref(''),dialog=ref(false),saving=ref(false),formRef=ref<FormInstance>();const blank=():Omit<EnterpriseRecord,'id'>&{id?:number}=>({enterpriseName:'',status:1});const form=ref(blank());const load=async()=>{loading.value=true;error.value='';try{data.value=(await getEnterpriseList()).data}catch(e){error.value=e instanceof Error?e.message:'网络异常'}finally{loading.value=false}};const edit=(row?:EnterpriseRecord)=>{form.value=row?{...row}:blank();dialog.value=true};const save=async()=>{if(!form.value.enterpriseName)return ElMessage.warning('请输入企业名称');saving.value=true;try{form.value.id?await updateEnterprise(form.value as EnterpriseRecord):await createEnterprise(form.value);dialog.value=false;ElMessage.success('企业保存成功');await load()}finally{saving.value=false}};const remove=async(row:EnterpriseRecord)=>{await ElMessageBox.confirm(`确认删除企业“${row.enterpriseName}”？`,'删除确认',{type:'warning'});await deleteEnterprise(row.id);await load()};onMounted(load)</script>
<template><article class="tech-panel"><div class="panel-head"><h2 class="panel-title">施工企业档案</h2><button class="tech-button" @click="edit()"><Plus :size="13"/>新增企业</button></div><ResourceState :loading="loading" :error="error" :empty="!data.length" @retry="load"><el-table :data="data"><el-table-column prop="enterpriseName" label="企业名称"/><el-table-column prop="unifiedSocialCreditCode" label="统一社会信用代码"/><el-table-column prop="legalRepresentative" label="法人"/><el-table-column prop="contactName" label="联系人"/><el-table-column prop="contactMobile" label="联系电话"/><el-table-column prop="qualificationInfo" label="资质信息"/><el-table-column label="操作"><template #default="{row}"><el-button link @click="edit(row)"><Edit3 :size="13"/>修改</el-button><el-button link type="danger" @click="remove(row)"><Trash2 :size="13"/>删除</el-button></template></el-table-column></el-table></ResourceState></article><el-dialog v-model="dialog" :title="form.id?'修改施工企业':'新增施工企业'" width="min(680px,92vw)"><el-form ref="formRef" :model="form" label-width="120px"><el-form-item label="企业名称" required><el-input v-model="form.enterpriseName"/></el-form-item><el-form-item label="统一信用代码"><el-input v-model="form.unifiedSocialCreditCode"/></el-form-item><el-form-item label="法人代表"><el-input v-model="form.legalRepresentative"/></el-form-item><el-form-item label="联系人"><el-input v-model="form.contactName"/></el-form-item><el-form-item label="联系电话"><el-input v-model="form.contactMobile"/></el-form-item><el-form-item label="企业地址"><el-input v-model="form.address"/></el-form-item><el-form-item label="资质信息"><el-input v-model="form.qualificationInfo" type="textarea"/></el-form-item></el-form><template #footer><button class="tech-button" :disabled="saving" @click="save">保存</button></template></el-dialog></template>
